import fs from'node:fs/promises';import zlib from'node:zlib';
const b="";const files=JSON.parse(zlib.gunzipSync(Buffer.from(b,'base64')).toString('utf8'));for(const [f,s]of Object.entries(files)){await fs.mkdir(f.includes('/')?f.slice(0,f.lastIndexOf('/')):'.',{recursive:true});await fs.writeFile(f,s)}await import('./build.mjs');
